SELECT r.message_id, r.provider, r.model, r.model_kind, r.status, r.cost, r.turn_id, r.error_code, r.error_message, r.finish_reason, r.prompt_tokens, r.prompt_cached_tokens, r.completion_tokens, r.total_tokens, r.prompt_audio_tokens, r.completion_reasoning_tokens, r.completion_audio_tokens, r.completion_accepted_prediction_tokens, r.completion_rejected_prediction_tokens, r.started_at, r.completed_at, r.latency_ms, r.trace_id, r.span_id, r.request_payload_id, r.response_payload_id, r.provider_request_payload_id, r.provider_response_payload_id, r.stream_payload_id, r.run_id, r.iteration FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM model_call c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)